example.code:
const word = "zebra";
const shift = 3;
const emoji = "😀";

let encoded = "";
for (let i = 0; i < word.length; i++) {
  const code = word.charCodeAt(i);
  encoded += String.fromCharCode((code - 97 + shift + 26) % 26 + 97);
}

console.log(`${word} -> ${encoded}`);
console.log(`Length: ${emoji.length}`);
console.log(`Characters: ${[...emoji].length}`);

